(() => {
  'use strict';
  const state = { findings: [], session: null, csrf: '', tab: 'overview', settings: null, readiness: null, config: null, scan: null, plan: null, job: null, busy: false, notice: null };
  const esc = (v) => String(v ?? '').replace(/[&<>"']/g, (c) => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const readable = (v) => String(v ?? '').replaceAll('_',' ').toLowerCase().replace(/^./, s => s.toUpperCase());
  const badge = (v) => { const x=String(v??'UNKNOWN').toUpperCase(); const tone=x==='PASS'||x==='COMPLIANT'||x==='DETECTED'||x==='READY'?'pass':x.includes('FAIL')||x==='ERROR'?'fail':x.includes('WARN')||x.includes('PENDING')||x.includes('AMBIGUOUS')?'warn':''; return `<span class="gr-auto-badge ${tone}">${esc(readable(x))}</span>`; };
  const values = (arr) => Array.isArray(arr)&&arr.length ? `<div class="gr-auto-values">${arr.map(v=>`<span class="gr-auto-value">${esc(v)}</span>`).join('')}</div>` : '<span style="color:#8a9ba5">—</span>';
  function currentFindingId(){ const m=(location.hash||'').match(/^#\/findings\/([^/?#]+)/); return m ? decodeURIComponent(m[1]) : ''; }
  async function ensureSession(force=false){ if(state.session&&!force) return state.session; const r=await fetch('/api/session',{credentials:'same-origin',cache:'no-store'}); const d=await r.json().catch(()=>null); if(!r.ok||!d) throw new Error(d?.message||`Session request failed (${r.status})`); state.session=d; state.csrf=d.csrfToken||''; return d; }
  async function api(path, body){ await ensureSession(); const opt={method:body===undefined?'GET':'POST',credentials:'same-origin',cache:'no-store',headers:{Accept:'application/json'}}; if(body!==undefined){ opt.headers['Content-Type']='application/json'; opt.headers['X-CSRF-Token']=state.csrf; opt.body=JSON.stringify(body); } const r=await fetch('/api'+path,opt); const d=await r.json().catch(()=>null); if(!r.ok) throw new Error(`${d?.code||'HTTP_'+r.status}: ${d?.message||'Request failed'}`); return d; }
  function setNotice(text,tone='success'){ state.notice={text,tone}; render(); }
  function root(){ return document.getElementById('gr-auto-panel'); }
  let returnFocus = null;
  const drafts = new Map();
  function captureDrafts(){ root()?.querySelectorAll('form').forEach(form=>{const data={};form.querySelectorAll('[name]').forEach(el=>data[el.name]=el.type==='checkbox'?el.checked:el.value);drafts.set(form.id,data);}); }
  function restoreDrafts(){ root()?.querySelectorAll('form').forEach(form=>{const data=drafts.get(form.id);if(data)form.querySelectorAll('[name]').forEach(el=>{if(Object.hasOwn(data,el.name)){if(el.type==='checkbox')el.checked=data[el.name];else el.value=data[el.name];}});}); }
  async function loadFindings(){try{const data=await api('/dashboard');state.findings=data.findings||[];render();}catch(e){state.notice={text:e.message,tone:'error'};render();}}
  function openPanel(tab){ returnFocus=document.activeElement;document.getElementById('root').inert=true;document.body.style.overflow='hidden'; state.tab=tab||state.tab; document.getElementById('gr-auto-panel')?.classList.add('open'); document.getElementById('gr-auto-backdrop')?.classList.add('open'); render(); if(state.tab==='overview') loadOverview(); if(state.tab==='setup') loadSetup(); if(state.tab==='plan')loadFindings(); root().querySelector('[data-action=close]')?.focus(); }
  function closePanel(){ document.getElementById('root').inert=false;document.body.style.overflow='';returnFocus?.focus();window.dispatchEvent(new CustomEvent('gr:refresh')); document.getElementById('gr-auto-panel')?.classList.remove('open'); document.getElementById('gr-auto-backdrop')?.classList.remove('open'); }
  async function loadOverview(){ try{ state.busy=true; render(); const [settings,readiness,config]=await Promise.all([api('/settings'),api('/automation/readiness'),api('/setup/config')]); state.settings=settings; state.readiness=readiness; state.config=config; }catch(e){state.notice={text:e.message,tone:'error'};}finally{state.busy=false;render();} }
  async function loadSetup(){ try{ state.busy=true; render(); const [settings,config,readiness]=await Promise.all([api('/settings'),api('/setup/config'),api('/automation/readiness')]); state.settings=settings; state.config=config; state.readiness=readiness; }catch(e){state.notice={text:e.message,tone:'error'};}finally{state.busy=false;render();} }
  function header(){ return `<div class="gr-auto-head"><div><h2>Əməliyyat mərkəzi</h2><p>Modulu seçin → plan hazırlayın → tətbiq edin</p></div><button class="gr-auto-close" data-action="close" aria-label="Paneli bağla">×</button></div><div class="gr-auto-tabs">${[['overview','Hazırlıq'],['setup','Sazlamalar'],['plan','Plan və tətbiq']].map(([id,label])=>`<button data-tab="${id}" class="${state.tab===id?'active':''}">${label}</button>`).join('')}</div>`; }
  function notice(){ return state.notice ? `<div role="alert" class="gr-auto-note ${esc(state.notice.tone||'')}">${esc(state.notice.text)}</div>` : ''; }
  function overview(){ const s=state.session, r=state.readiness, cfg=state.config; let checks=''; if(r?.checks) checks=r.checks.map(c=>`<div class="gr-auto-row"><div><strong>${esc(c.label)}</strong><small>${esc(c.message)}${c.required?'':' · advisory'}</small></div>${badge(c.status)}</div>`).join(''); return `${notice()}<div class="gr-auto-card"><div class="gr-auto-section-title"><h3>İcra mühiti</h3>${s?badge(s.mode):''}</div><dl class="gr-auto-kv"><dt>Mode</dt><dd>${esc(s?.mode||'Loading')}</dd><dt>Operator</dt><dd>${esc(s?.operator||'—')}</dd><dt>Identity</dt><dd>${esc(s?.identityStrategy||'—')}</dd><dt>Local config</dt><dd>${cfg?.exists?'Present':'Not configured'}</dd><dt>Writes</dt><dd>${cfg?.enableWrites?'ENABLED':'Disabled'}</dd></dl></div><div class="gr-auto-card"><div class="gr-auto-section-title"><h3>Mühitin hazırlığı</h3><button class="gr-auto-btn" data-action="readiness" ${state.busy?'disabled':''}>${state.busy?'Yoxlanılır…':'Hazırlığı yoxla'}</button></div>${r?`<div class="gr-auto-note ${r.ready?'success':'warn'}">${r.ready?'All required readiness checks passed.':'One or more required readiness checks have not passed.'}</div>${checks}`:'<p>Run readiness to validate runtime, AD/DC access, identity and policy prerequisites.</p>'}</div><div class="gr-auto-card"><h3>Automated operating flow</h3><p>Daily operation stays in the UI; the launcher handles build/start prerequisites.</p><div class="gr-auto-row"><div><strong>1 · Configure</strong><small>Save domain, DC, approved GPOs, OUs, hosts and operators.</small></div></div><div class="gr-auto-row"><div><strong>2 · Benchmark</strong><small>Modullar səhifəsindən parametr və hədəf seçin. İlkin scan tələb olunmur.</small></div></div><div class="gr-auto-row"><div><strong>3 · Safe plan</strong><small>Analyze → choose safe approved GPO → preview → zero-write dry run.</small></div></div><div class="gr-auto-row"><div><strong>4 · Apply</strong><small>Write remains a separate explicitly authorized action in the finding workflow.</small></div></div></div>`; }
  function setup(){ const c=state.config||{}; const lines=(v)=>esc((v||[]).join('\n')); const win=String(state.settings?.mode||state.session?.mode||'').toUpperCase()==='WINDOWS'; return `${notice()}<div class="gr-auto-card"><div class="gr-auto-section-title"><div><h3>Windows / AD sazlamaları</h3><p style="margin:3px 0 0;color:#81939c;font-size:10px">Saving forces EnableWrites=false and requests a controlled launcher restart.</p></div>${c.exists?badge('READY'):badge('NOT_CONFIGURED')}</div><form id="gr-setup-form"><div class="gr-auto-grid"><label class="gr-auto-field">Management HTTPS URL<input name="urls" required placeholder="https://gpo-remediator.example.com:5443" value="${esc(c.urls||'')}"></label><label class="gr-auto-field">AD domain<input name="domain" required placeholder="example.com" value="${esc(c.domain||'')}"></label><label class="gr-auto-field">Writable domain controller<input name="domainController" required placeholder="dc01.example.com" value="${esc(c.domainController||'')}"></label><label class="gr-auto-field">Backup path<input name="backupPath" required placeholder="C:\\ProgramData\\GpoRemediator\\Backups" value="${esc(c.backupPath||'C:\\ProgramData\\GpoRemediator\\Backups')}"></label><label class="gr-auto-field">İcazəli GPO GUID-ləri (hər sətirdə bir)<textarea name="approvedGpoIds" required>${lines(c.approvedGpoIds)}</textarea></label><label class="gr-auto-field">İcazəli OU-lar (hər sətirdə bir tam DN)<textarea name="authorizedOus" required>${lines(c.authorizedOus)}</textarea></label><label class="gr-auto-field">İcazəli hədəflər (hər sətirdə bir FQDN)<textarea name="allowedHosts" required>${lines(c.allowedHosts)}</textarea></label><label class="gr-auto-field">İcazəli operatorlar (DOMAIN\\user)<textarea name="allowedOperators" required>${lines(c.allowedOperators)}</textarea></label></div><div class="gr-auto-actions"><button class="gr-auto-btn primary" ${state.busy?'disabled':''}>Yoxla, saxla və yenidən başlat</button><button type="button" class="gr-auto-btn" data-action="readiness">Hazırlığı yoxla</button></div></form></div>${state.readiness?`<div class="gr-auto-card"><div class="gr-auto-section-title"><h3>Readiness before writes</h3>${badge(state.readiness.ready?'PASS':'FAIL')}</div>${state.readiness.checks.map(x=>`<div class="gr-auto-row"><div><strong>${esc(x.label)}</strong><small>${esc(x.message)}</small></div>${badge(x.status)}</div>`).join('')}</div>`:''}${win&&c.exists?`<div class="gr-auto-card"><h3>GPO-ya yazma icazəsi</h3><p>Enabling writes requires readiness PASS and the exact confirmation phrase. Apply still performs preview, backup, scope and verification checks.</p><label class="gr-auto-field">Confirmation phrase<input id="gr-write-confirm" placeholder="${c.enableWrites?'DISABLE WRITES':'ENABLE WRITES'}"></label><div class="gr-auto-actions"><button class="gr-auto-btn ${c.enableWrites?'':'danger'}" data-action="write-mode" data-enable="${c.enableWrites?'false':'true'}">${c.enableWrites?'Disable writes & restart':'Enable writes after readiness & restart'}</button>${badge(c.enableWrites?'WRITES_ENABLED':'WRITES_DISABLED')}</div></div>`:`<div class="gr-auto-note">Write mode becomes available here only after the service starts in real Windows mode with a saved configuration.</div>`}`; }
  function scan(){ const r=state.scan; return `${notice()}<div class="gr-auto-card"><h3>Hədəfi skan edin</h3><p>Skan parametrləri oxuyur, GPO-da dəyişiklik etmir. Oxunmayan nəticələr ayrıca göstərilir.</p><form id="gr-scan-form"><div class="gr-auto-grid"><label class="gr-auto-field">Hədəfin tam DNS adı (FQDN)<input name="hostname" required maxlength="253" value="${esc(state.session?.mode==='MOCK'?'SRV-APP-01.prosol.az':'')}" placeholder="srv-app-01.example.com"></label><label class="gr-auto-field">Hədəfin rolu<select name="profile"><option>Auto</option><option>MemberServer</option><option>DomainController</option><option>Workstation</option></select></label></div><div class="gr-auto-actions"><button class="gr-auto-btn primary" ${state.busy?'disabled':''}>${state.busy?'Skan edilir…':'Skanı başlat'}</button></div></form></div>${r?`<div class="gr-auto-card"><div class="gr-auto-section-title"><div><h3>${esc(r.target.hostname)}</h3><p style="margin:3px 0 0;color:#81939c;font-size:10px">${esc(r.target.operatingSystem)} · ${esc(r.target.profile)}</p></div><span>${badge(r.nonCompliant?'FAIL':r.unavailable||!r.results?.length?'WARN':'PASS')}</span></div><dl class="gr-auto-kv"><dt>Uyğun</dt><dd>${esc(r.compliant)}</dd><dt>Uyğunsuz</dt><dd>${esc(r.nonCompliant)}</dd><dt>Oxunmadı</dt><dd>${esc(r.unavailable)}</dd><dt>Yeni tapıntılar</dt><dd>${esc(r.findingsCreated)}</dd></dl><div class="gr-auto-table-wrap" style="margin-top:14px"><table class="gr-auto-table"><thead><tr><th>Control</th><th>Observed</th><th>Expected</th><th>Status</th><th>Finding</th></tr></thead><tbody>${(r.results||[]).map(x=>`<tr><td><strong>${esc(x.controlCode)}</strong><br><small>${esc(x.title)}</small><br><small>${esc(x.code)} · ${esc(x.message)}</small></td><td>${values(x.actualValue)}</td><td>${values(x.expectedValue)}</td><td>${badge(x.status)}</td><td>${x.findingId?`<a href="#/findings/${encodeURIComponent(x.findingId)}" data-action="close">Open →</a>`:'—'}</td></tr>`).join('')}</tbody></table></div></div>`:''}`; }
  function plan(){ const fid=currentFindingId(); const p=state.plan; return `${notice()}<div class="gr-auto-card"><h3>Dəyişiklik planını hazırlayın</h3><p>Parametrin mənbəyi və uyğun GPO seçilir, təsir dairəsi yoxlanır. Bu addımda dəyişiklik yazılmır.</p><form id="gr-plan-form"><label class="gr-auto-field">Seçilmiş parametr<select name="findingId" required><option value="">Parametri seçin…</option>${state.findings.map(f=>`<option value="${esc(f.id)}" ${f.id===fid?'selected':''}>${esc(f.control.controlId)} · ${esc(f.control.title)} — ${esc(f.target.hostname)} · ${esc(f.id.slice(0,8))}</option>`).join('')}${fid&&!state.findings.some(f=>f.id===fid)?`<option selected value="${esc(fid)}">Cari tapıntı · ${esc(fid)}</option>`:''}</select></label><div class="gr-auto-actions"><button class="gr-auto-btn primary" ${state.busy?'disabled':''}>${state.busy?'Plan hazırlanır…':'Planı hazırla və yoxla'}</button>${fid?`<a class="gr-auto-link" href="#/findings/${encodeURIComponent(fid)}" data-action="close">Current finding</a>`:''}</div></form></div>${p?`<div class="gr-auto-card"><div class="gr-auto-section-title"><h3>Planın nəticəsi</h3>${badge(p.dryRun&&p.writes===0?'PASS':'WARN')}</div><dl class="gr-auto-kv"><dt>Mənbə təhlili</dt><dd>${esc(p.analysis.status)} · ${esc(p.analysis.confidence)}</dd><dt>Seçilmiş GPO</dt><dd>${esc(p.impact.gpo.name)}<br><code>${esc(p.impact.gpo.id)}</code></dd><dt>Strategy</dt><dd>${esc(p.selection.strategy)}</dd><dt>Geniş təsir dairəsi</dt><dd>${p.impact.broadImpact?'Yes — acknowledge before Apply':'No'}</dd><dt>Dry run</dt><dd>${p.dryRun?'Completed':'Not completed'}</dd><dt>Yazılmış dəyişikliklər</dt><dd>${esc(p.writes)}</dd><dt>Can read/edit/link/verify</dt><dd>${[p.preflight.canRead,p.preflight.canEdit,p.preflight.canLink,p.preflight.canVerify].map(v=>v?'✓':'×').join(' / ')}</dd></dl>${p.analysis.message?`<div class="gr-auto-note">${esc(p.analysis.message)}</div>`:''}${(p.impact.warnings||[]).length?`<div class="gr-auto-note warn">${p.impact.warnings.map(esc).join('<br>')}</div>`:''}${(p.preflight.errors||[]).length?`<div class="gr-auto-note error">${p.preflight.errors.map(esc).join('<br>')}</div>`:''}<div class="gr-auto-note warn">Apply is intentionally separate from planning. It requires an explicit confirmation and the backend still revalidates preview freshness, permissions, scope and backup requirements.</div><form id="gr-apply-form"><div class="gr-auto-grid"><label class="gr-auto-field"><span><input type="checkbox" name="runGpUpdate" checked> GPO dəyişikliyindən sonra gpupdate icra et</span></label><label class="gr-auto-field"><span><input type="checkbox" name="authorizeRestart"> Parametr tələb edərsə hədəfin yenidən başlamasına icazə ver</span></label>${p.impact.broadImpact?`<label class="gr-auto-field gr-auto-span2"><span><input type="checkbox" name="ackBroad"> GPO-nun geniş təsir dairəsini nəzərdən keçirdim və təsdiqləyirəm</span></label>`:''}<label class="gr-auto-field gr-auto-span2">Bu planı təsdiqləmək üçün APPLY yazın<input name="confirmation" autocomplete="off" placeholder="APPLY"></label></div><div class="gr-auto-actions"><button class="gr-auto-btn danger" ${state.busy||state.job?'disabled':''}>${state.job?'Əməliyyat yaradıldı':'Təsdiqlə və tətbiq et'}</button><a class="gr-auto-link" href="#/findings/${encodeURIComponent(p.impact.findingId)}" data-action="close">Tapıntını aç →</a>${state.job?`<a class="gr-auto-link" href="#/jobs/${encodeURIComponent(state.job.id)}" data-action="close">Əməliyyatı izlə →</a>`:''}</div></form></div>`:''}`; }
  function render(){ const panel=root(); if(!panel)return; const focused=panel.contains(document.activeElement)?{name:document.activeElement.name,id:document.activeElement.id,action:document.activeElement.dataset.action}:null; let body=''; if(state.busy&&!state.session) body='<div class="gr-auto-card"><p>Connecting to the application…</p></div>'; else if(state.tab==='setup') body=setup(); else if(state.tab==='scan') body=scan(); else if(state.tab==='plan') body=plan(); else body=overview(); panel.innerHTML=header()+`<div class="gr-auto-body" aria-busy="${state.busy}">${body}</div>`;restoreDrafts();if(state.busy)panel.querySelectorAll('button:not([data-action="close"]),input,select,textarea').forEach(el=>el.disabled=true);if(focused){const match=focused.name?[...panel.querySelectorAll('[name]')].find(el=>el.name===focused.name):focused.id?document.getElementById(focused.id):focused.action?[...panel.querySelectorAll('[data-action]')].find(el=>el.dataset.action===focused.action):null;(match&&!match.disabled?match:panel.querySelector('[data-action=close]'))?.focus();} }
  function lines(v){ return String(v||'').split(/[\n;]/).map(x=>x.trim()).filter(Boolean); }
  async function saveSetup(form){ const f=new FormData(form); const payload={urls:String(f.get('urls')||'').trim(),domain:String(f.get('domain')||'').trim(),domainController:String(f.get('domainController')||'').trim(),approvedGpoIds:lines(f.get('approvedGpoIds')),authorizedOus:lines(f.get('authorizedOus')),allowedHosts:lines(f.get('allowedHosts')),allowedOperators:lines(f.get('allowedOperators')),backupPath:String(f.get('backupPath')||'').trim(),autoRestart:true}; try{state.busy=true;state.notice=null;render();const r=await api('/setup/config',payload);state.notice={text:'Configuration validated and saved. Writes remain disabled. Launcher restart requested.',tone:'success'};state.config=await api('/setup/config').catch(()=>state.config);render();if(r.restartScheduled){setTimeout(()=>{location.href=payload.urls.replace(/\/$/,'')+'/#/settings';},3500);}}catch(e){state.notice={text:e.message,tone:'error'};render();}finally{state.busy=false;render();} }
  async function doScan(form){ const f=new FormData(form); try{state.busy=true;state.notice=null;state.scan=null;render();state.scan=await api('/automation/scan',{hostname:String(f.get('hostname')||'').trim(),profile:String(f.get('profile')||'Auto')});state.notice={text:`Skan tamamlandı. ${state.scan.nonCompliant} uyğunsuzluq, ${state.scan.unavailable} oxunmayan parametr, ${state.scan.findingsCreated} yeni tapıntı.`,tone:'success'};}catch(e){state.notice={text:e.message,tone:'error'};}finally{state.busy=false;render();} }
  async function doPlan(form){ const f=new FormData(form); const id=String(f.get('findingId')||'').trim(); try{state.busy=true;state.notice=null;state.plan=null;state.job=null;drafts.delete('gr-apply-form');render();state.plan=await api(`/findings/${encodeURIComponent(id)}/safe-plan`,{});state.notice={text:`Safe plan prepared with ${state.plan.writes} policy writes during dry run.`,tone:state.plan.writes===0?'success':'warn'};}catch(e){state.notice={text:e.message,tone:'error'};}finally{state.busy=false;render();} }

  async function doApply(form){
    if(state.job||state.busy)return;
    if(!state.plan){ state.notice={text:'Prepare a safe plan before Apply.',tone:'error'}; render(); return; }
    const f=new FormData(form); const confirmation=String(f.get('confirmation')||'').trim();
    if(confirmation!=='APPLY'){ state.notice={text:'Type APPLY exactly to create the Apply job.',tone:'error'}; render(); return; }
    const options={runGpUpdate:f.get('runGpUpdate')==='on',authorizeRestart:f.get('authorizeRestart')==='on',acknowledgeBroadImpact:state.plan.impact.broadImpact?f.get('ackBroad')==='on':false};
    if(state.plan.impact.broadImpact&&!options.acknowledgeBroadImpact){ state.notice={text:'This preview has broad GPO impact. Review and acknowledge it before Apply.',tone:'error'}; render(); return; }
    try{state.busy=true;state.notice=null;render();state.job=await api(`/findings/${encodeURIComponent(state.plan.impact.findingId)}/apply`,{previewId:state.plan.impact.id,options});state.notice={text:`Apply job ${state.job.id} was created. Open the execution record to follow verification.`,tone:'success'};}catch(e){state.notice={text:e.message,tone:'error'};}finally{state.busy=false;render();}
  }
  async function writeMode(btn){ const enable=btn.dataset.enable==='true'; const confirmation=document.getElementById('gr-write-confirm')?.value||''; try{state.busy=true;state.notice=null;render();const r=await api('/setup/write-mode',{enable,confirmation,autoRestart:true});state.notice={text:`Write mode ${r.enableWrites?'enabled':'disabled'}. Launcher restart requested.`,tone:'success'};render();if(r.restartScheduled)setTimeout(()=>location.reload(),3500);}catch(e){state.notice={text:e.message,tone:'error'};render();}finally{state.busy=false;render();} }
  function injectNav(){ const nav=document.querySelector('.sidebar nav'); if(!nav||nav.querySelector('.gr-auto-nav'))return; const b=document.createElement('button');b.type='button';b.className='nav-link gr-auto-nav';b.innerHTML='<svg aria-hidden="true" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"><path d="M4 6h16M4 12h16M4 18h16"/><circle cx="8" cy="6" r="2"/><circle cx="16" cy="12" r="2"/><circle cx="10" cy="18" r="2"/></svg>Əməliyyat mərkəzi';b.addEventListener('click',()=>openPanel('overview'));nav.appendChild(b); }
  function init(){ window.addEventListener('gr:open',e=>openPanel(e.detail?.tab||'overview'));
    document.addEventListener('keydown',e=>{const panel=root();if(!panel?.classList.contains('open'))return;if(e.key==='Escape')closePanel();if(e.key==='Tab'){const focusable=[...panel.querySelectorAll('button:not(:disabled),a[href],input:not(:disabled),select:not(:disabled),textarea:not(:disabled)')];const first=focusable[0],last=focusable[focusable.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}}); const backdrop=document.createElement('div');backdrop.id='gr-auto-backdrop';backdrop.addEventListener('click',closePanel);document.body.appendChild(backdrop);const panel=document.createElement('aside');panel.id='gr-auto-panel';panel.setAttribute('aria-label','Əməliyyat mərkəzi');panel.setAttribute('role','dialog');panel.setAttribute('aria-modal','true');document.body.appendChild(panel);panel.addEventListener('input',captureDrafts);panel.addEventListener('change',e=>{captureDrafts();if(e.target.name==='findingId'&&state.plan&&e.target.value!==state.plan.impact.findingId){state.plan=null;state.job=null;drafts.delete('gr-apply-form');render();}});const launch=document.createElement('button');launch.id='gr-auto-launcher';launch.innerHTML='<span class="gr-pulse"></span>Əməliyyatlar';launch.addEventListener('click',()=>openPanel('overview'));document.body.appendChild(launch);panel.addEventListener('click',(e)=>{const t=e.target.closest('[data-action],[data-tab]');if(!t)return;if(t.dataset.tab){if(state.busy)return;state.tab=t.dataset.tab;state.notice=null;render();if(state.tab==='plan')loadFindings();if(state.tab==='overview')loadOverview();if(state.tab==='setup')loadSetup();return;}const a=t.dataset.action;if(a==='close')closePanel();else if(a==='readiness')loadOverview().then(()=>{state.tab=state.tab==='setup'?'setup':'overview';render();});else if(a==='write-mode')writeMode(t);});panel.addEventListener('submit',(e)=>{e.preventDefault();if(e.target.id==='gr-setup-form')saveSetup(e.target);else if(e.target.id==='gr-scan-form')doScan(e.target);else if(e.target.id==='gr-plan-form')doPlan(e.target);else if(e.target.id==='gr-apply-form')doApply(e.target);});const observer=new MutationObserver(injectNav);observer.observe(document.body,{childList:true,subtree:true});injectNav();window.addEventListener('hashchange',()=>{if(location.hash==='#/settings'){openPanel('setup');return;}if(state.tab==='plan'){drafts.delete('gr-plan-form');const form=document.getElementById('gr-plan-form');if(form)form.remove();state.plan=null;state.job=null;drafts.delete('gr-apply-form');render();}});ensureSession().then(()=>{render();injectNav();if(location.hash==='#/settings'||state.session?.setupRequired){state.notice=state.session?.setupRequired?{text:'Windows / AD sazlaması tamamlanmayıb. Yerli sazlama rejimi açılıb; domenə dəyişiklik edilmir.',tone:'warn'}:null;setTimeout(()=>openPanel('setup'),180);}}).catch(e=>{state.notice={text:e.message,tone:'error'};render();});render(); }
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init();
})();
